3b907db5876ff4e12f48953' as sample_id , 'cb4ececd-dcb4-517c-a0bc-ddafd23813b9' as report_id , current_date - 3 as test_date , current_date - 3 as report_created_date , (current_date - 1)::timestamp as last_printed_at union all select 5 as row_no , 'COMPREHENSIVE_PANEL' as test_classification , 'RP' as disease , 'Respiratory Tract Infections' as disease_name , 'ABI' as panel_code , 'Respiratory Comprehensive Panel' as panel_name , 10 as detected_analytes_count , 1 as print_count , 'b009a5f7798b5fdc35935933cfbd7e01930a7aeb63b907db5876ff4e12f48953' as sample_id , 'e5925354-8ffc-b090-ecc0-cd0944afd27f' as report_id , current_date - 4 as test_date , current_date - 4 as report_created_date , (current_date - 1)::timestamp as last_printed_at union all select 6 as row_no , 'OTHER_PANELS' as test_classification , 'OTHERS' as disease , 'Other Diseases' as disease_name , 'N_TEV' as panel_code , 'Other Pathogens Detection' as panel_name , 4 as detected_analytes_count , 0 as print_count , 'dfae5c9fe9508c46fb5ced6bc5c885594dcf9f1670664abb3359ab6e48c5b0fb' as sample_id , 'd9031cb6-e11a-8245-e824-5c9ed74ea9ea' as report_id , current_date - 5 as test_date , current_date - 5 as report_created_date , null::timestamp as last_printed_at union all select 7 as row_no , 'OTHER_PANELS' as test_classification , 'HPV' as disease , 'Human Papillomavirus Infections' as disease_name , 'N2_HR' as panel_code , 'Novaplex II HPV28 Detection' as panel_name , 10 as detected_analytes_count , 0 as print_count , 'e72f66026b3e166321f10c17c21b5cd57145dab3943e67d093627035020cf800' as sample_id , '9905507f-a179-9d38-269b-ff7a2589a685' as report_id , current_date - 6 as test_date , current_date - 6 as report_created_date , null::timestamp as last_printed_at union all select 8 as row_no , 'OTHER_PANELS' as test_classification , 'HPV' as disease , 'Human Papillomavirus Infections' as disease_name , 'N2_HPV28' as panel_code , 'Novaplex II HPV28 Detection' as panel_name , 4 as detected_analytes_count , 1 as print_count , '6796a717a4a617c8c639ba595e331dec135b6121e28ec23a0f8b517b779fbe51' as sample_id , 'b25a457f-a8da-a4fe-2ff0-4cb47f79a59c' as report_id , current_date - 7 as test_date , current_date - 7 as report_created_date , (current_date - 1)::timestamp as last_printed_at union all select 9 as row_no , 'OTHER_PANELS' as test_classification , 'RP' as disease , 'Respiratory Tract Infections' as disease_name , 'RP1+RP2' as panel_code , 'Respiratory Panel 1 + 2' as panel_name , 10 as detected_analytes_count , 0 as print_count , '4e2b85248d473cf46d9a684c5d4a2d7260d81e5bf0b6b656b43754b206a9bef1' as sample_id , '415d0160-7bfb-64fa-0b7e-faf0fe064e86' as report_id , current_date - 8 as test_date , current_date - 8 as report_created_date , null::timestamp as last_printed_at union all select 10 as row_no , 'OTHER_PANELS' as test_classification , 'RP' as disease , 'Respiratory Tract Infections' as disease_name , 'RP1+RP2+RP3+RP4' as panel_code , 'Respiratory Panel 1 + 2 + 3 + 4' as panel_name , 4 as detected_analytes_count , 0 as print_count , '617a79c70e5449b52404a764d6b72f1d5c0622e6ab07c06a6b25df923e25cc20' as sample_id , '02812b6b-6db0-fa4a-3865-82985bd645cf' as report_id , current_date - 9 as test_date , current_date - 9 as report_created_date , null::timestamp as last_printed_at )
, cte_input_samples as ( select unnest(array[
#{sampleId}
]::text[]) as sample_id )
, cte_filtered as ( select a.* from cte_reports as a where a.test_date <= current_date
and a.sample_id in ( select z.sample_id from cte_input_samples as z )
and a.test_classification = #{testClassification}
and a.disease = #{disease}
and a.test_date >= current_date
and a.test_date >= current_date - 6
and a.test_date >= current_date - interval '1 month'
) select count(1) as report_count , count(distinct a.sample_id) as found_sample_id_count
, ( select count(distinct x.sample_id) from cte_reports as x where x.sample_id in ( select z.sample_id from cte_input_samples as z ) and not exists ( select 1 from cte_filtered as y where y.sample_id = x.sample_id ) ) as no_results_count , ( select count(1) from cte_input_samples as x where not exists ( select 1 from cte_reports as y where y.sample_id = x.sample_id ) ) as not_found_count
, 0::bigint as no_results_count , 0::bigint as not_found_count
from cte_filtered as a

